import sys

def main():
    input_data = sys.stdin.read().strip().split()
    if not input_data:
        return
    L = int(input_data[0])
    R = int(input_data[1])
    C = int(input_data[2])

    if abs(L - R) >= C:
        result = min(max(L, R), min(L, R) + C) * 2
        print(result)
    else:
        diff = abs(L - R)
        if L > R:
            R += diff
        else:
            L += diff
        C -= diff
        result = (C // 2 + L) * 2
        print(result)

if __name__ == "__main__":
    main()

